cat > /home/user/myproject/build_chart.py << 'EOF'
import altair as alt
import json
from vega_datasets import data

# Load TopoJSON URL for US state boundaries
states = alt.topo_feature(data.us_10m.url, 'states')

# URL for population_engineers_hurricanes dataset
pop_url = data.population_engineers_hurricanes.url

# Build the chart
chart = (
    alt.Chart(states)
    .mark_geoshape()
    .transform_lookup(
        lookup='id',
        from_=alt.LookupData(
            pop_url,
            key='id',
            fields=['engineers', 'state'],
        ),
    )
    .encode(
        color=alt.Color('engineers:Q', scale=alt.Scale(scheme='blues')),
        tooltip=['state:N', 'engineers:Q'],
    )
    .project(type='albersUsa')
    .properties(width=700, height=400)
)

# Get the Vega-Lite spec as dict
spec = chart.to_dict()

# Build a self-contained HTML file with the spec in a JSON block, rendered via vegaEmbed
html = f"""<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>US State-Level Engineers Choropleth</title>
  <script type="text/javascript" src="https://cdn.jsdelivr.net/npm/vega@6"></script>
  <script type="text/javascript" src="https://cdn.jsdelivr.net/npm/vega-lite@6.4.1"></script>
  <script type="text/javascript" src="https://cdn.jsdelivr.net/npm/vega-embed@7"></script>
  <style>
    #vis {{
      width: 100%;
      display: flex;
    }}
  </style>
</head>
<body>
  <div id="vis"></div>
  <script type="application/json" id="vis-spec">
{json.dumps(spec, indent=2)}
  </script>
  <script>
    (function() {{
      var spec = JSON.parse(document.getElementById('vis-spec').textContent);
      var embedOpt = {{"mode": "vega-lite"}};
      function showError(el, error) {{
          el.innerHTML = ('<div style="color:red;">'
                          + '<p>JavaScript Error: ' + error.message + '</p>'
                          + "<p>This usually means there's a typo in your chart specification. "
                          + 'See the javascript console for the full traceback.</p>'
                          + '</div>');
          throw error;
      }}
      const el = document.getElementById('vis');
      vegaEmbed('#vis', spec, embedOpt).catch(error => showError(el, error));
    }})();
  </script>
</body>
</html>
"""

with open('chart.html', 'w') as f:
    f.write(html)

print('Chart saved to chart.html')
EOF

